-- Chinese, Sinhala and Tamil translations of the 6 seeded study guides (0100).
-- Adds a language only when that guide doesn't have it yet, so translations
-- edited in Admin → Website → Study Guides are never overwritten.
--
-- No USE statement -- see Database/tools/apply-migrations.ps1 / ENVIRONMENTS.md.

UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "斯里兰卡学生留学中国完全指南", "seoTitle": "斯里兰卡学生留学中国完全指南 | 普罗顿教育", "description": "斯里兰卡学生赴华留学须知全汇总：专业项目、入学要求、费用、奖学金、X1 学生签证，以及 Proton Education Services（普罗顿教育服务）如何从申请到毕业全程协助。", "bodyHtml": "<p>中国已成为斯里兰卡学生最热门的留学目的地之一——大学获国际认可、英语授课项目丰富、费用低于许多西方国家，奖学金也十分慷慨。本指南将一步步带您了解整个留学流程。</p><h2>斯里兰卡学生为何选择中国</h2><p>中国高校在工程、商科、信息技术、医学和理科等领域提供国际认可的学位，其中许多项目全英文授课。学费和生活费普遍低于英国、澳大利亚和美国，中国政府和各高校还专门为国际学生设立了奖学金。</p><p>斯中两国在教育和经济领域联系紧密，既了解两国、又掌握一定中文的毕业生，在贸易、旅游、科技和基础设施等行业备受青睐。</p><h2>可选专业与项目</h2><ul><li>大专及预科项目</li><li>本科学位（一般 4 年，医学专业更长）</li><li>硕士及博士项目</li><li>汉语言项目（从零基础到高级，含 HSK 备考）</li><li>在获批高校就读英语授课的 MBBS（临床医学）</li></ul><h2>一般入学要求</h2><p>申请本科通常需要提供 G.C.E. A/L（高级水平考试）成绩、有效护照、体检记录；英语授课项目需提供英语能力证明，中文授课项目则需 HSK 成绩。硕士申请者需持有获认可的学士学位，通常还需推荐信和学习计划。</p><p>具体要求因学校和专业而异，申请前务必核实目标项目的要求——这也是 Proton（普罗顿）为您代劳的工作之一。</p><h2>从斯里兰卡到中国校园：分步流程</h2><ul><li>确定专业、学历层次以及心仪的城市或大学。</li><li>准备材料：护照、A/L 或学位证书及成绩单、照片、体检表以及语言证书（如有）。</li><li>向大学提交申请（符合条件者可同时申请奖学金）。</li><li>收到大学寄发的录取通知书和 JW201/JW202 签证申请表。</li><li>通过中国驻科伦坡大使馆/签证中心申请学生签证（长期项目办理 X1 签证）。</li><li>赴华后到大学报到；持 X1 签证者需在入境后申请居留许可。</li></ul><h2>普罗顿教育服务如何助您一臂之力</h2><p>Proton（普罗顿）是一家持牌的斯里兰卡公司，在中国各地设有合作伙伴和办事处。我们协助您选择合适的大学和专业、准备并提交申请、申请奖学金、办理学生签证，并在您抵达后帮助您安顿下来——从申请到毕业，您只需对接一个值得信赖的团队。</p>", "faq": [{"q": "斯里兰卡学生可以在中国用英语学习吗？", "a": "可以。许多中国高校开设全英文授课的学位项目，涵盖商科、工程、信息技术和医学（MBBS）等。若先完成汉语课程，也可选择中文授课项目。"}, {"q": "斯里兰卡学生赴华留学需要哪些学历条件？", "a": "申请本科通常需要 A/L 成绩、有效护照和体检记录；英语授课项目可能要求英语能力证明。硕士项目需持有获认可的学士学位。具体要求因校而异。"}, {"q": "来华留学需要办理哪种签证？", "a": "学习期限超过 180 天的学生申请 X1 学生签证；较短的项目办理 X2 签证。申请时需提供大学出具的录取通知书和 JW201/JW202 表。"}, {"q": "斯里兰卡学生在中国有奖学金吗？", "a": "有。CSC (国家留学基金管理委员会) 中国政府奖学金以及众多高校和省级奖学金均向斯里兰卡学生开放，部分奖学金可覆盖学费、住宿费并提供每月生活补助。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'study-in-china-from-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
GO
UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "斯里兰卡 A/L 考试后何去何从：升学选择全解析", "seoTitle": "斯里兰卡 A/L 考试后的升学选择 | 普罗顿", "description": "完成 G.C.E. A/L（高级水平考试）后该怎么选？比较斯里兰卡国立大学、私立学位、职业教育以及赴华留学等路径，并了解如何做出选择。", "bodyHtml": "<p>拿到 A/L 成绩是人生的重要时刻，也常常令人迷茫。无论是否被国立大学录取，您的选择都比想象中更多。下面为您逐一梳理各条路径。</p><h2>1. 斯里兰卡国立大学</h2><p>国立大学的录取由大学拨款委员会（UGC）根据 A/L 成绩和 Z 分数决定。名额有限，许多成绩优秀的合格学生也未能被心仪的专业录取。</p><h2>2. 斯里兰卡私立及海外合作学位</h2><p>私立院校提供本地学位及与外国大学合作的学位。请确认该学历是否获得认可（例如获 UGC 或颁发学位的外国大学认可），并仔细比较总费用。</p><h2>3. 职业及专业资格</h2><p>文凭、NVQ 资格证书以及会计、信息技术、酒店管理等专业课程，既可直接就业，也可作为日后攻读学位的基础。</p><h2>4. 出国留学——为何中国是理想之选</h2><p>出国留学可获得国际认可的学位、国际化经历以及第二语言能力。对斯里兰卡学生而言，中国优势突出：大学获认可、英语授课项目多、费用低于许多西方国家，并有 CSC (国家留学基金管理委员会) 中国政府奖学金等资助。</p><p>A/L 后的热门方向包括工程、信息技术、商科、国际贸易、医学（MBBS）以及汉语言项目，这些都能为您开启连接斯里兰卡与中国的职业之路。</p><h2>如何做出选择</h2><ul><li>您真正想学什么专业？它能通向哪些职业？</li><li>您的总预算（学费、生活费、交通费）是多少？奖学金能否覆盖一部分？</li><li>该学历在您希望就业的地方是否获得认可？</li><li>您是否希望获得国际经历并掌握第二语言？</li></ul>", "faq": [{"q": "如果没有被国立大学录取，A/L 之后还能做什么？", "a": "您可以攻读私立或海外合作学位、考取职业或专业资格，或出国留学——例如赴中国攻读本科，那里有面向斯里兰卡学生的英语授课项目和奖学金。"}, {"q": "凭 A/L 成绩可以去中国留学吗？", "a": "可以。中国高校的本科项目接受 G.C.E. A/L（高级水平考试）成绩。具体要求取决于学校和专业；Proton Education Services（普罗顿教育服务）可以帮您查看哪些项目与您的成绩相匹配。"}, {"q": "斯里兰卡学生在中国最热门的专业有哪些？", "a": "工程、信息技术与计算机科学、商科与国际贸易、医学（MBBS）以及汉语言都是最受欢迎的选择。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'what-to-do-after-al-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
GO
UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "斯里兰卡学生中国留学签证（X1 / X2）申请指南", "seoTitle": "斯里兰卡学生中国留学签证（X1/X2）申请指南 | 普罗顿", "description": "斯里兰卡学生如何申请中国学生签证：X1 与 X2 签证的区别、所需材料（录取通知书、JW201/JW202 表）、在科伦坡的申请步骤以及入境后的居留许可办理。", "bodyHtml": "<p>拿到大学录取后，下一步就是办理学生签证。以下介绍斯里兰卡学生申请中国学生签证的流程及所需准备。</p><h2>X1 还是 X2——您需要哪种学生签证？</h2><ul><li>X1 签证：适用于学习期限超过 180 天的项目（学位课程、长期语言项目）。入境中国后需转办居留许可。</li><li>X2 签证：适用于 180 天及以下的短期项目（短期课程、交流项目、暑期学校）。</li></ul><h2>通常需要准备的材料</h2><ul><li>有效护照（剩余有效期充足且有空白签证页）及近期照片</li><li>填写完整的签证申请表</li><li>中国高校出具的录取通知书原件</li><li>JW201 或 JW202《外国留学人员来华签证申请表》（由大学签发）</li><li>X1 签证需提供体检记录（停留超过 6 个月者）</li></ul><h2>申请步骤</h2><ul><li>收到大学寄发的录取通知书和 JW201/JW202 表。</li><li>在线填写签证申请表并预约递交时间。</li><li>前往科伦坡的中国签证申请服务中心递交材料并缴费。</li><li>领取贴有签证的护照。</li><li>持 X1 签证者，入境中国后需到当地公安局出入境管理部门申请居留许可（一般在 30 天内）。</li></ul><h2>普罗顿签证支持</h2><p>Proton（普罗顿）帮助您逐项核对材料、正确填写表格，并为入境后办理居留许可做好准备——减少延误和拒签。签证政策可能变化，我们会在您申请前确认最新要求。</p>", "faq": [{"q": "X1 签证和 X2 签证有什么区别？", "a": "X1 适用于学习期限超过 180 天的情况，入境后需在中国转办居留许可；X2 适用于 180 天及以下的学习。"}, {"q": "什么是 JW202 表？", "a": "JW201/JW202 是由中国高校随录取通知书一同签发的官方《外国留学人员来华签证申请表》，申请学生签证时必须提供。"}, {"q": "斯里兰卡人在哪里申请中国学生签证？", "a": "通过中国驻斯里兰卡大使馆在科伦坡设立的签证申请服务机构办理。Proton Education Services（普罗顿教育服务）可指导您准备材料和预约。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'china-student-visa-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
GO
UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "面向斯里兰卡学生的中国政府（CSC）奖学金", "seoTitle": "斯里兰卡学生申请中国政府（CSC）奖学金 | 普罗顿", "description": "斯里兰卡学生如何获得中国政府（CSC）奖学金及其他中国奖学金：资助内容、申请资格、申请流程以及打造优秀申请的建议。", "bodyHtml": "<p>奖学金能让留学中国的费用大大降低。最知名的是由国家留学基金管理委员会（CSC）管理的中国政府奖学金，此外还有众多高校和省级奖学金。</p><h2>CSC 全额奖学金可覆盖的内容</h2><ul><li>学费</li><li>校内住宿费</li><li>每月生活补助（生活费）</li><li>综合医疗保险</li></ul><h2>中国奖学金的类型</h2><ul><li>中国政府奖学金（CSC）——双边项目及高校自主招生项目</li><li>省、市政府奖学金</li><li>高校奖学金（全额或部分减免学费）</li><li>孔子学院奖学金（用于汉语学习）</li></ul><h2>如何申请</h2><ul><li>选定专业，并确认该校接收奖学金申请者。</li><li>准备材料：学历证书和成绩单、学习计划或研究计划、推荐信、护照及体检表。</li><li>在截止日期前提交 CSC 网上申请和大学申请（通常于每年年初开放申请）。</li><li>等待评审结果，以及录取通知书和签证申请表。</li></ul><h2>打造优秀申请的建议</h2><ul><li>尽早申请——截止日期非常严格。</li><li>撰写清晰、具体的学习计划，将个人目标与项目紧密结合。</li><li>请熟悉您学业表现的老师或讲师撰写推荐信。</li><li>确保所有材料完整且信息一致。</li></ul>", "faq": [{"q": "斯里兰卡学生可以获得中国政府奖学金吗？", "a": "可以。斯里兰卡学生可以申请 CSC (国家留学基金管理委员会) 中国政府奖学金，以及高校和省级奖学金。"}, {"q": "CSC 奖学金包括哪些内容？", "a": "全额奖学金通常涵盖学费、住宿费、每月生活补助和医疗保险；部分奖学金则覆盖其中的若干项。"}, {"q": "应该什么时候申请中国奖学金？", "a": "大多数奖学金在每年年初开放申请，对应 9 月入学，因此请提前几个月开始准备。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'chinese-government-scholarship-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
GO
UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "斯里兰卡学生赴华攻读医学（MBBS）", "seoTitle": "斯里兰卡学生赴华读 MBBS 指南 | 普罗顿教育", "description": "为考虑赴华攻读 MBBS 的斯里兰卡学生提供的指南：英语授课临床医学、如何选择获批高校、入学要求，以及毕业后回斯里兰卡执业（SLMC 与 ERPM 考试）。", "bodyHtml": "<p>医学是斯里兰卡学生赴华留学最热门的原因之一。选对大学比什么都重要——以下是您需要关注的要点。</p><h2>中国的英语授课 MBBS</h2><p>中国教育部公布了可面向国际学生开展英语授课临床医学（MBBS）的高校名单。项目一般为期六年，包括临床实习。</p><h2>如何选择合适的大学</h2><ul><li>确认该校获准面向国际学生开展英语授课 MBBS。</li><li>核实是否获得 Sri Lanka Medical Council (SLMC, 斯里兰卡医学委员会) 认可并被列入《世界医学院校名录》。</li><li>考察临床培训条件：教学医院及接触病例的机会。</li><li>比较总费用、所在城市以及对国际学生的支持服务。</li></ul><h2>毕业后回斯里兰卡行医</h2><p>海外医学院毕业生须满足 Sri Lanka Medical Council (SLMC, 斯里兰卡医学委员会) 的注册要求，其中包括通过行医注册考试（ERPM）。选择大学前，请务必确认 SLMC 的最新规定。</p>", "faq": [{"q": "中国的 MBBS 学位在斯里兰卡有效吗？", "a": "毕业生满足 Sri Lanka Medical Council (SLMC, 斯里兰卡医学委员会) 的要求（包括通过 ERPM 考试）后即可在斯里兰卡执业。请选择获批高校，并事先核实 SLMC 的最新规定。"}, {"q": "在中国读 MBBS 需要几年？", "a": "中国的英语授课 MBBS 项目通常为六年，其中包括一年实习。"}, {"q": "在中国读 MBBS 需要会中文吗？", "a": "课程以英语授课，但大学通常会开设汉语课，因为临床培训期间需要与患者沟通。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'mbbs-in-china-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
GO
UPDATE syst.Guide SET ContentJSON = JSON_MODIFY(ContentJSON, '$.zh', JSON_QUERY(N'{"title": "学习中文与 HSK 考试：斯里兰卡学生指南", "seoTitle": "斯里兰卡学生学中文与 HSK 考试指南 | 普罗顿", "description": "为什么中文能力对斯里兰卡学生和职场人士至关重要、HSK 等级如何划分、在中国的汉语言项目，以及 HSK 如何助力升学与奖学金申请。", "bodyHtml": "<p>对于任何与中国打交道的斯里兰卡学生或职场人士来说，中文都是一项宝贵的技能。HSK 考试是证明中文水平的标准方式。</p><h2>什么是 HSK？</h2><p>HSK（汉语水平考试）是面向母语非汉语者的官方中文水平考试。等级越高，代表阅读、听力和写作能力越强。中文授课的学位项目和部分奖学金会要求达到一定的 HSK 等级。</p><h2>学习中文的途径</h2><ul><li>在中国高校就读汉语言项目（一学期至一年或更长）</li><li>“语言+学位”衔接路径：先读一年语言，再攻读中文授课学位</li><li>出发前在斯里兰卡参加中文课程</li></ul><h2>为什么中文很重要</h2><ul><li>可申请中文授课学位项目，并获得更多奖学金机会</li><li>让在华日常生活以及临床或实习安排更加顺利</li><li>有助于在斯中之间的贸易、旅游、物流和科技领域发展职业</li></ul>", "faq": [{"q": "攻读中文授课学位需要什么 HSK 等级？", "a": "这取决于学校和专业；许多本科项目要求中等水平的 HSK 等级。英语授课项目不要求 HSK。"}, {"q": "我可以在中国参加汉语言项目吗？", "a": "可以——中国各地高校均为国际学生开设汉语言项目，学制从一学期到一年甚至更长。"}]}')), UpdatedDate = GETDATE()
WHERE Slug = 'learn-chinese-hsk-sri-lanka' AND JSON_QUERY(ContentJSON, '$.zh') IS NULL
